import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

test('grant, write, release', async () => {
  const h = await createHost();
  assert.deepEqual(await h.acquire('c0'), { ok: true });
  assert.equal((await h.acquire('c0')).ok, false);
  assert.equal((await h.acquire('c9')).ok, false);
  assert.equal(await h.client('c9'), null);
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]), [['c0', 'lease', 'Acquire', { from: 'c0' }]]);
  await h.deliverAll();
  assert.deepEqual(await h.client('c0'), { status: 'holding', token: 1, writing: false });
  assert.deepEqual(await h.lease(), { holder: 'c0', token: 1, writes: 0 });
  assert.deepEqual(await h.write('c0'), { ok: true });
  assert.equal((await h.write('c0')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: 'c0', token: 1, writes: 1 });
  assert.deepEqual(await h.write('c0'), { ok: true });
  const w2 = (await h.inFlight())[0];
  await h.deliver(w2.id);
  assert.equal((await h.inFlight())[0].action, 'WriteRefused');
  await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: 'c0', token: 1, writes: 1 });
  assert.deepEqual(await h.release('c0'), { ok: true });
  assert.equal((await h.client('c0'))!.status, 'releasing');
  assert.equal((await h.acquire('c0')).ok, false);
  const rel = (await h.inFlight())[0];
  assert.deepEqual(rel.data, { from: 'c0', token: 1 });
  await h.deliver(rel.id);
  assert.deepEqual((await h.inFlight()).map((m) => [m.to, m.action, m.data]), [['c0', 'Released', {}]]);
  await h.deliverAll();
  assert.equal((await h.client('c0'))!.status, 'idle');
  assert.deepEqual(await h.lease(), { holder: null, token: 1, writes: 1 });
  await h.acquire('c1');
  await h.deliverAll();
  assert.deepEqual(await h.client('c1'), { status: 'holding', token: 2, writing: false });
  await h.release('c1');
  await h.deliverAll();
  await h.acquire('c0');
  await h.deliverAll();
  assert.deepEqual(await h.client('c0'), { status: 'idle', token: 1, writing: false });
  await (h as any).__dispose();
